// src/main.tsx
// ============================================================================
// 🎯 main.tsx — Entry point with PWA service worker registration
// ============================================================================
// Fixes P2 #19. Registers the SW (auto-generated by vite-plugin-pwa) and
// shows a non-blocking toast when an update is available.
// ============================================================================

import React from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import { AppThemeProvider } from './components/theme/AppThemeProvider';
import { registerSW } from 'virtual:pwa-register';

import App from './App';
import { ErrorFallback } from './components/ErrorFallback';
import { SentryErrorBoundary, initSentry } from './lib/sentry';
import { isReloadingForNewVersion, reloadOnStaleVersion } from './lib/staleVersion';
import { listenForDownloads, rememberFirstTouch } from './lib/acquisition';
import { AuthProvider } from './contexts/AuthContext';
import { NotificationProvider } from './contexts/NotificationContext';
import { TutorialProvider } from './contexts/TutorialContext';
import { LocaleProvider } from './i18n/runtime';
import './index.css';

// Errors and real-user speed (no-op without VITE_SENTRY_DSN). Before anything
// else, so the boundary below and the page-load measure have a client.
initSentry();

// ============================================================================
// PWA service worker
// ============================================================================
const updateSW = registerSW({
  onNeedRefresh() {
    // Show a non-blocking toast (handled inside the app via custom event)
    window.dispatchEvent(
      new CustomEvent('pwa:update-available', {
        detail: {
          accept: () => updateSW(true),
        },
      })
    );
  },
  onOfflineReady() {
    console.info('[PWA] Application prête à fonctionner hors ligne.');
  },
  onRegisteredSW(_swUrl, r) {
    if (!r) return;
    // Look for a new version every hour while the app is open, and as soon as
    // the visitor comes back to the tab. Skipped offline and in a background
    // tab. A check that can't reach sw.js (network drop, PC waking from sleep)
    // changes nothing — the running version keeps working — so it is dropped
    // silently and retried next time instead of surfacing as an error.
    let lastCheck = Date.now();
    const checkForUpdate = () => {
      if (document.visibilityState !== 'visible' || !navigator.onLine || r.installing) return;
      lastCheck = Date.now();
      r.update().catch(() => undefined);
    };
    setInterval(checkForUpdate, 60 * 60 * 1000);
    document.addEventListener('visibilitychange', () => {
      if (Date.now() - lastCheck > 10 * 60 * 1000) checkForUpdate();
    });
  },
  onRegisterError(error) {
    console.error('[PWA] SW registration error:', error);
  },
});

// A screen of the previous version that no longer exists after a deploy:
// reload once to get the new version instead of a blank page.
reloadOnStaleVersion();

// Where the visitor came from (before the router changes the URL), and the
// free-template downloads, counted anonymously (src/lib/acquisition.ts).
rememberFirstTouch();
listenForDownloads();

// ============================================================================
// Mount
// ============================================================================
ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <SentryErrorBoundary
      fallback={({ error }) =>
        // Reloading for a new version: the page is about to go, show nothing.
        isReloadingForNewVersion() ? <></> : <ErrorFallback error={error} resetError={() => window.location.reload()} />
      }
    >
    <BrowserRouter>
      <LocaleProvider>
      <AppThemeProvider>
      <AuthProvider>
        <NotificationProvider>
          <TutorialProvider>
            <App />
          </TutorialProvider>
        </NotificationProvider>
      </AuthProvider>
      </AppThemeProvider>
      </LocaleProvider>
    </BrowserRouter>
    </SentryErrorBoundary>
  </React.StrictMode>
);
